            <Paragraph>
                Зелёный мыс — <Word>
                    <Bold />
                    это не Батуми.
                </Word> Это отдельное село (Мцване Концхи) примерно в 8–10 км к северу от центра, в Аджарском районе. Море
                там действительно чистое и красиво-зелёно, но как место для повседневной жизни без машины с двумя детьми оно
                тебе, честно, не подойдёт. Разберу по твоим вопросам.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
