        <Message
            at="2026-06-11T18:19:58.380100Z"
        >
            <Origin>019eb7e9-2e11-770b-90cb-81355fccf0c4</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>
                Да, ты понимаешь в целом верно — но с одним важным уточнением про форму города. Дай подтвержу цифрами.
            </Paragraph>
            <Action>
                Searched the web for “Батуми размер города площадь население компактный центр пешком вытянут вдоль
                побережья”
            </Action>
            <Paragraph>Да, в целом ты понимаешь правильно. Уточню, чтобы у тебя была точная картина.</Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Батуми — небольшой и компактный город.
                </Word> Население около 160 тысяч, площадь ~65 км². Главное — его <Word>
                    <Bold />
                    форма
                </Word>: город не «квадратный», а <Word>
                    <Bold />
                    вытянут узкой полосой вдоль моря
                </Word> (бухта-полумесяц растянута примерно на 7 км с севера на юг). То есть он длинный вдоль берега, но
                <Word>
                    <Bold />
                    узкий вглубь от моря
                </Word> — а это как раз то, что тебе на руку.
            </Paragraph>
            <Paragraph>
                Что это значит на практике: <Word>
                    <Bold />
                    почти из любой точки центральной части до моря действительно близко.
                </Word> Жилые кварталы в центре стоят всего в несколько улиц от бульвара, поэтому <Word>
                    <Bold />
                    15 минут пешком до моря из центра — это реалистично, а часто и быстрее
                </Word> (5–10 минут). Обе квартиры, что ты присылала, — как раз такие: несколько кварталов от пляжа.
            </Paragraph>
            <Paragraph>
                Одна честная оговорка, чтобы не было сюрприза: «15 минут» работает для <Word>
                    <Bold />
                    центральной приморской зоны
                </Word>. Поскольку город длинный, есть и удалённые районы вглубь и к окраинам (Бони, в сторону аэропорта и
                т.д.) — оттуда до моря уже дальше. Поэтому правило простое: <Word>
                    <Bold />
                    смотри не «центр вообще», а близость конкретной квартиры к бульвару
                </Word> по карте. Раз ты и так выбираешь варианты у Ниношвили/Багратиони/Ардагани — все они в этой удобной
                полосе.
            </Paragraph>
            <Paragraph>
                Ещё плюс компактности: <Word>
                    <Bold />
                    по центру в принципе почти всё пешком
                </Word> — магазины, кафе, рынок, бульвар. А такси по городу очень дешёвое (часто 4–7 лари за поездку), так
                что даже когда лень идти пешком или нужно дальше — это не проблема и без машины.
            </Paragraph>
            <Paragraph>
                Если хочешь, на любой из присланных квартир могу прикинуть по карте примерное время пешком до пляжа — пришли
                точный адрес дома, и посчитаю.
            </Paragraph>
        </Message>
